ST.xhtml:p:
(* PI heater control with anti-windup.
   err > 0 means the milk is too cold -> call for heat. *)
  KP := 8.0;
  KI := 1.5;
  err := INT_TO_REAL(Setpoint) - INT_TO_REAL(Temp);

  (* provisional output = proportional + accumulated integral *)
  out := KP * err + integ;

  (* ANTI-WINDUP: only grow the integral while we are NOT saturated.
     Climbing from cold, out is pinned at 100%, so we freeze the
     integral instead of letting it wind up past the setpoint. *)
  IF (out > 0.0) AND (out < 100.0) THEN
      integ := integ + KI * err * 0.02;   (* 0.02 s = the 20 ms scan *)
  END_IF;

  out := LIMIT(0.0, KP * err + integ, 100.0);

  (* dry-fire / phase interlock: force heat off and drop the integral *)
  IF Inhibit THEN
      out   := 0.0;
      integ := 0.0;
  END_IF;

  Power := REAL_TO_INT(out);
